contracts/AccessControl.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

contract AccessControl {
    error Capita__NotOwner();

    address public owner;

    event OwnershipTransfer(address indexed newOwner);

    constructor(address _owner) {
        owner = _owner;
    }

    modifier onlyOwner() {
        if (msg.sender != owner) revert Capita__NotOwner();
        _;
    }

    function transferOwnership(address _newOwner) external onlyOwner {
        owner = _newOwner;
        emit OwnershipTransfer(_newOwner);
    }
}

contracts/CapitaFundingFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";
import {ChainFundMe} from "./ChainFundMe.sol";
import {CapitaPoints} from "./CapitaPoints.sol";
import {AccessControl} from "./AccessControl.sol";

contract CapitaFundingFactory is AccessControl {
    using Clones for address;

    /*//////////////////////////////////////////////////////////////
                                 ERRORS
    //////////////////////////////////////////////////////////////*/

    error CapitaFundingFactory__NotModerator();
    error CapitaFundingFactory__InsufficientFee();
    error CapitaFundingFactory__WithdrawFailed();
    error CapitaFundingFactory__TokenNotAllowed(address _tokenAddress);
    error CapitaFundingFactory__InvalidAddress(address);
    error CapitaFundingFactory__FeeCannotBeLessThan_1();
    error CapitaFundingFactory__FeeCannotBeGreaterThan_20();
    error CapitaFundingFactory__ContractPaused();
    error CapitaFundingFactory__MaxOf5TokensExceeded();
    error CapitaFundingFactory__InvalidDatesSet();
    error CapitaFundingFactory__CapitaPointsAlreadySet();
    error CapitaFundingFactory__CampaignApproved(address);
    error CapitaFundingFactory__UnverifiedUser();

    /*//////////////////////////////////////////////////////////////
                            STATE VARIABLES
    //////////////////////////////////////////////////////////////*/

    uint8 public platformFee = 5; // 5%. Enforced in ChainFundMe
    uint256 public deployedCampaignsCount;

    address public priceFeedAddress;

    address public immutable chainFundMeImplementation;
    address public immutable stableCoinAddress;
    address public capitaTokenAddress;
    address public feeWalletAddress;
    bool public paused; // pause factory contract
    bool public limitsEnabled = true; // Enforced in ChainFundMe

    CapitaPoints public capitaPoints;

    mapping(uint256 => address) public indexToDeployedCampaigns; // Maps campaign ID to contract address
    mapping(address => bool) public moderators;
    mapping(address => address[]) private userCampaigns; // Tracks each user's chainFundMe contracts
    mapping(address => bool) public otherAcceptedTokensAddresses;
    mapping(address => bool) public verifiedCreators;

    /*//////////////////////////////////////////////////////////////
                                 EVENTS
    //////////////////////////////////////////////////////////////*/

    event ChainFundMeCreated(
        address indexed creator,
        address indexed fundMeAddress
    );
    event ModeratorAdded(address indexed moderator);
    event ModeratorRemoved(address indexed moderator);
    event CapitaPointsAddressSet(address indexed capitaPointsAddress);
    event FeeWithdrawn(uint256 amount);
    event UpdatedFeeWalletAddress(address indexed _feeWalletAddress);
    event CapitaFactoryPaused(bool isPaused);
    event PlatformFeeUpdated(uint8 newFee);
    event AcceptableTokenSet(address indexed token, bool accepted);
    event UpdatedLimitsEnabled(bool indexed enabled);
    /*//////////////////////////////////////////////////////////////
                               MODIFIERS
    //////////////////////////////////////////////////////////////*/

    modifier onlyModerator() {
        if (!moderators[msg.sender])
            revert CapitaFundingFactory__NotModerator();
        _;
    }

    modifier onlyCampaignOwner(address _campaignAddress) {
        if (msg.sender != ChainFundMe(_campaignAddress).owner()) {
            revert AccessControl.Capita__NotOwner();
        }
        _;
    }

    /*//////////////////////////////////////////////////////////////
                               FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    constructor(
        address _stableCoinAddress,
        address _capitaTokenAddress,
        address _feeWalletAddress,
        address _priceFeedAddress
    ) AccessControl(msg.sender) {
        stableCoinAddress = _stableCoinAddress;
        capitaTokenAddress = _capitaTokenAddress;
        if (_feeWalletAddress == address(0))
            revert CapitaFundingFactory__InvalidAddress(_feeWalletAddress);
        if (_priceFeedAddress == address(0))
            revert CapitaFundingFactory__InvalidAddress(_priceFeedAddress);

        feeWalletAddress = _feeWalletAddress;
        chainFundMeImplementation = address(new ChainFundMe());
        priceFeedAddress = _priceFeedAddress;

        addModerator(msg.sender);
    }

    /*//////////////////////////////////////////////////////////////
                           EXTERNAL FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function removeModerator(address _moderator) external onlyOwner {
        moderators[_moderator] = false;
        emit ModeratorRemoved(_moderator);
    }

    function setCapitaPointsAddress(
        address _capitaPointsAddress
    ) external onlyOwner {
        capitaPoints = CapitaPoints(_capitaPointsAddress);
        emit CapitaPointsAddressSet(_capitaPointsAddress);
    }

    function createChainFundMe(
        uint256 startTime,
        uint256 endTime,
        string memory _metadataUri,
        address[] memory _otherTokenAddresses
    ) external {
        if (paused) revert CapitaFundingFactory__ContractPaused();

        uint256 addressesLength = _otherTokenAddresses.length;

        if (addressesLength > 5)
            revert CapitaFundingFactory__MaxOf5TokensExceeded();

        if (address(capitaPoints) == address(0))
            revert CapitaFundingFactory__InvalidAddress(address(capitaPoints));

        if (startTime >= endTime || startTime < block.timestamp)
            revert CapitaFundingFactory__InvalidDatesSet();

        for (uint i = 0; i < addressesLength; i++) {
            address _otherTokenAddress = _otherTokenAddresses[i];
            if (_otherTokenAddress == address(0)) {
                revert CapitaFundingFactory__InvalidAddress(_otherTokenAddress);
            }
            if (!checkAcceptableTokenAddress(_otherTokenAddress)) {
                revert CapitaFundingFactory__TokenNotAllowed(
                    _otherTokenAddress
                );
            }
        }

        address chainFundMeClone = chainFundMeImplementation.clone();

        ChainFundMe(chainFundMeClone).initialize(
            msg.sender,
            startTime,
            endTime,
            _metadataUri,
            stableCoinAddress,
            capitaTokenAddress,
            _otherTokenAddresses,
            address(this)
        );
        indexToDeployedCampaigns[deployedCampaignsCount] = address(
            chainFundMeClone
        ); // Store campaign ID to contract address
        deployedCampaignsCount++;
        userCampaigns[msg.sender].push(address(chainFundMeClone)); // Store campaign for creator

        emit ChainFundMeCreated(msg.sender, address(chainFundMeClone));
    }

    function chainFundMe_fundChainFundMe(
        address _campaignAddress,
        address _otherToken,
        uint256 _amount
    ) external payable {
        address sender = msg.sender;
        uint256 value = msg.value;
        ChainFundMe(_campaignAddress).deposit{value: value}(
            _otherToken,
            _amount,
            sender
        );

        if (_otherToken == stableCoinAddress) {
            // mint points for the user
            capitaPoints.mintPointsUSD(sender, _amount);
        }
        if (_otherToken == address(0)) {
            // mint points for the user
            capitaPoints.mintPointsETH(sender, value);
        }
    }

    function chainFundMe_approveWithdraw(
        address _campaignAddress
    ) external onlyModerator {
        ChainFundMe(_campaignAddress).approveWithdraw();
    }

    function chainFundMe_batchWithdrawApproval(
        address[] memory _fundMeAddresses
    ) external onlyModerator {
        for (uint256 i = 0; i < _fundMeAddresses.length; i++) {
            ChainFundMe(_fundMeAddresses[i]).approveWithdraw();
        }
    }

    function chainFundMe_revokeApproval(
        address _campaignAddress,
        bool revoke
    ) external onlyOwner {
        ChainFundMe(_campaignAddress).revokeApproval(revoke);
    }

    function chainFundMe_pauseChainFundMeContract(
        address _campaignAddress,
        bool pause
    ) external onlyModerator {
        ChainFundMe(_campaignAddress).updatePause(pause);
    }

    function chainFundMe_approveFunding(
        address _campaignAddress
    ) external onlyModerator {
        ChainFundMe chainFundMe = ChainFundMe(_campaignAddress);
        bool approved = chainFundMe.fundingApproved();
        address campaignOwner = chainFundMe.owner();
        uint256 basePoints = capitaPoints.BASE_POINTS();
        if (approved)
            revert CapitaFundingFactory__CampaignApproved(_campaignAddress);
        chainFundMe.updateFundingApproval();
        capitaPoints.mintPoints(campaignOwner, basePoints);
    }

    function chainFundMe_batchApproveFunding(
        address[] memory _fundMeAddresses
    ) external onlyModerator {
        for (uint256 i = 0; i < _fundMeAddresses.length; i++) {
            ChainFundMe(_fundMeAddresses[i]).updateFundingApproval();
        }
    }

    function chainFundMe_disapproveFunding(
        address _campaignAddress,
        bool _disapproved
    ) external onlyModerator {
        ChainFundMe(_campaignAddress).updateFundingDisapproval(_disapproved);
    }

    function chainFundMe_batchDisapproveFunding(
        address[] memory _fundMeAddresses,
        bool _disapproved
    ) external onlyModerator {
        for (uint256 i = 0; i < _fundMeAddresses.length; i++) {
            ChainFundMe(_fundMeAddresses[i]).updateFundingDisapproval(
                _disapproved
            );
        }
    }

    function chainFundMe_withdrawAllFunds(
        address _campaignAddress
    ) external onlyCampaignOwner(_campaignAddress) {
        chainFundMe_withdrawETH(_campaignAddress);
        chainFundMe_withdrawTokens(_campaignAddress);
    }

    function chainFundMe_withdrawETH(
        address _campaignAddress
    ) public onlyCampaignOwner(_campaignAddress) {
        ChainFundMe chainFundMe = ChainFundMe(_campaignAddress);
        address campaignOwner = chainFundMe.owner();
        bool isMinted = chainFundMe.isWithdrawalPointsMinted();

        chainFundMe.withdrawETH();
        if (!isMinted) {
            chainFundMe.updateIsWithdrawalPointsMinted();
            uint256 basePoints = capitaPoints.BASE_POINTS();
            capitaPoints.mintPoints(campaignOwner, basePoints);
        }
    }

    function chainFundMe_withdrawTokens(
        address _campaignAddress
    ) public onlyCampaignOwner(_campaignAddress) {
        ChainFundMe chainFundMe = ChainFundMe(_campaignAddress);
        address campaignOwner = chainFundMe.owner();
        bool isMinted = chainFundMe.isWithdrawalPointsMinted();

        chainFundMe.withdrawOtherTokens();
        if (!isMinted) {
            chainFundMe.updateIsWithdrawalPointsMinted();
            uint256 basePoints = capitaPoints.BASE_POINTS();
            capitaPoints.mintPoints(campaignOwner, basePoints);
        }
    }

    function setAcceptableToken(address _tokenAddress) external onlyOwner {
        otherAcceptedTokensAddresses[_tokenAddress] = true;
        emit AcceptableTokenSet(_tokenAddress, true);
    }

    function removeTokenAddress(address _tokenAddress) external onlyOwner {
        otherAcceptedTokensAddresses[_tokenAddress] = false;
        emit AcceptableTokenSet(_tokenAddress, false);
    }

    function updatePlatformFee(uint8 _platformFee) external onlyOwner {
        if (_platformFee < 1)
            revert CapitaFundingFactory__FeeCannotBeLessThan_1();
        if (_platformFee > 20)
            revert CapitaFundingFactory__FeeCannotBeGreaterThan_20();
        platformFee = _platformFee;
        emit PlatformFeeUpdated(_platformFee);
    }

    function updateFeeWalletAddress(
        address _feeWalletAddress
    ) external onlyOwner {
        if (address(capitaPoints) != address(0)) {
            revert CapitaFundingFactory__CapitaPointsAlreadySet();
        }
        feeWalletAddress = _feeWalletAddress;
        emit UpdatedFeeWalletAddress(_feeWalletAddress);
    }

    function updatePaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit CapitaFactoryPaused(_paused);
    }

    function updateCapitaTokenAddress(
        address _capitaTokenAddress
    ) external onlyOwner {
        capitaTokenAddress = _capitaTokenAddress;
    }

    function updateLimitsEnabled(bool _enabled) external onlyOwner {
        limitsEnabled = _enabled;
        emit UpdatedLimitsEnabled(_enabled);
    }

    function verifyCreator(
        address _creator,
        bool _verify
    ) external onlyModerator {
        verifiedCreators[_creator] = _verify;
    }

    /*//////////////////////////////////////////////////////////////
                            PUBLIC FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function checkAcceptableTokenAddress(
        address _tokenAddress
    ) public view returns (bool) {
        return otherAcceptedTokensAddresses[_tokenAddress];
    }

    function addModerator(address _moderator) public onlyOwner {
        moderators[_moderator] = true;
        emit ModeratorAdded(_moderator);
    }

    /*//////////////////////////////////////////////////////////////
                            GETTER FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function getUserCampaigns(
        address _user
    ) external view returns (address[] memory) {
        return userCampaigns[_user];
    }

    function getDeployedCampaigns() external view returns (address[] memory) {
        address[] memory campaigns = new address[](deployedCampaignsCount);
        for (uint256 i = 0; i < deployedCampaignsCount; i++) {
            campaigns[i] = indexToDeployedCampaigns[i];
        }
        return campaigns;
    }
}

contracts/CapitaPoints.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {AggregatorV3Interface} from "@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol";
import {PriceFeed} from "./lib/PriceFeed.sol";
import {AccessControl} from "./AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract CapitaPoints is AccessControl, ReentrancyGuard {
    /*//////////////////////////////////////////////////////////////
                                 ERRORS
    //////////////////////////////////////////////////////////////*/

    error CapitaPoints__NotFactory();
    error CapitaPoints__NotOwner();
    error CapitaPoints__InsufficientETHForTier();
    error CapitaPoints__MultiplierTierAlreadyOwned();
    error CapitaPoints__InvalidAddress();
    error CapitaPoints__Paused();

    /*//////////////////////////////////////////////////////////////
                                LIBRARY
    //////////////////////////////////////////////////////////////*/

    using PriceFeed for uint256;

    /*//////////////////////////////////////////////////////////////
                           ENUMS AND STRUCTS
    //////////////////////////////////////////////////////////////*/

    enum MultiplierTier {
        BASE,
        BRONZE,
        SILVER,
        GOLD,
        PLATINUM,
        DIAMOND
    }

    struct MultiplierInfo {
        uint256 multiplierPrice; // Price in USD (wei)
        uint32 multiplier; // Multiplier value
    }

    struct SpenderStatus {
        MultiplierTier multiplierTier;
        uint32 multiplier;
    }

    /*//////////////////////////////////////////////////////////////
                            STATE VARIABLES
    //////////////////////////////////////////////////////////////*/

    uint256 private constant BASE_TIER_PRICE = 0;
    uint32 private constant BASE_TIER_MULTIPLIER = 1;

    uint256 private constant BRONZE_TIER_PRICE = 10 ether; // 10USD in wei
    uint32 private constant BRONZE_TIER_MULTIPLIER = 5;

    uint256 private constant SILVER_TIER_PRICE = 30 ether;
    uint32 private constant SILVER_TIER_MULTIPLIER = 10;

    uint256 private constant GOLD_TIER_PRICE = 50 ether;
    uint32 private constant GOLD_TIER_MULTIPLIER = 15;

    uint256 private constant PLATINUM_TIER_PRICE = 70 ether;
    uint32 private constant PLATINUM_TIER_MULTIPLIER = 20;

    uint256 private constant DIAMOND_TIER_PRICE = 90 ether;
    uint32 private constant DIAMOND_TIER_MULTIPLIER = 25;

    uint256 public constant BASE_POINTS = 100 ether; // 10 points in wei

    AggregatorV3Interface public immutable priceFeedAddress;

    address public fundingFactoryAddress;

    bool public paused;

    mapping(address => uint256) public spenderToPointsEarned;
    mapping(address => SpenderStatus) public spenderStatus;
    mapping(MultiplierTier => MultiplierInfo) private multiplierTierInfo;

    /*//////////////////////////////////////////////////////////////
                                 EVENTS
    //////////////////////////////////////////////////////////////*/

    event PurchaseMultiplier(
        address indexed spender,
        MultiplierTier indexed multiplierTier,
        uint256 pricePaid,
        uint256 multiplier
    );

    event PointsMinted(address indexed spender, uint256 amountEarned);
    event MultiplierPriceUpdated(MultiplierTier indexed tier, uint256 newPrice);
    event MultiplierUpdated(MultiplierTier indexed tier, uint256 multiplier);
    event MultiplierInfoUpdated(
        MultiplierTier indexed tier,
        uint256 multiplier,
        uint256 newPrice
    );

    event NewFundingFactoryAddress(address indexed newFundingFactoryAddress);
    event Paused(bool isPaused);

    /*//////////////////////////////////////////////////////////////
                               MODIFIERS
    //////////////////////////////////////////////////////////////*/

    modifier onlyFactory() {
        if (msg.sender != fundingFactoryAddress && msg.sender != address(this))
            revert CapitaPoints__NotFactory();
        _;
    }

    modifier whenNotPaused() {
        if (paused) revert CapitaPoints__Paused();
        _;
    }

    /*//////////////////////////////////////////////////////////////
                               FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    constructor(
        address _fundingFactoryAddress,
        address _priceFeedAddress
    ) AccessControl(msg.sender) {
        if (
            _priceFeedAddress == address(0) ||
            _fundingFactoryAddress == address(0)
        ) revert CapitaPoints__InvalidAddress();
        priceFeedAddress = AggregatorV3Interface(_priceFeedAddress);
        fundingFactoryAddress = _fundingFactoryAddress;

        // Initialize multiplier tiers with prices and values
        updateMultiplierTierInfo(
            MultiplierTier.BASE,
            BASE_TIER_PRICE,
            BASE_TIER_MULTIPLIER
        );
        updateMultiplierTierInfo(
            MultiplierTier.BRONZE,
            BRONZE_TIER_PRICE,
            BRONZE_TIER_MULTIPLIER
        );
        updateMultiplierTierInfo(
            MultiplierTier.SILVER,
            SILVER_TIER_PRICE,
            SILVER_TIER_MULTIPLIER
        );
        updateMultiplierTierInfo(
            MultiplierTier.GOLD,
            GOLD_TIER_PRICE,
            GOLD_TIER_MULTIPLIER
        );
        updateMultiplierTierInfo(
            MultiplierTier.PLATINUM,
            PLATINUM_TIER_PRICE,
            PLATINUM_TIER_MULTIPLIER
        );
        updateMultiplierTierInfo(
            MultiplierTier.DIAMOND,
            DIAMOND_TIER_PRICE,
            DIAMOND_TIER_MULTIPLIER
        );
    }

    /*//////////////////////////////////////////////////////////////
                           EXTERNAL FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function purchaseMultiplier(
        MultiplierTier _multiplierTier
    ) external payable whenNotPaused nonReentrant {
        address sender = msg.sender;
        MultiplierInfo memory selectedMultiplier = multiplierTierInfo[
            _multiplierTier
        ];

        SpenderStatus memory spender = spenderStatus[sender];

        // Ensure spender does not already own this multiplier
        if (_multiplierTier == spender.multiplierTier) {
            revert CapitaPoints__MultiplierTierAlreadyOwned();
        }

        // Convert ETH to USD and check if enough was sent
        uint256 amount = msg.value;
        uint256 amountToUsd = amount.ethToUsd(priceFeedAddress);
        uint256 priceInUsd = selectedMultiplier.multiplierPrice;

        if (amountToUsd < priceInUsd) {
            revert CapitaPoints__InsufficientETHForTier();
        }

        uint256 priceInEth = priceInUsd.usdToEth(priceFeedAddress);
        if (amount > priceInEth) {
            (bool success, ) = payable(sender).call{value: amount - priceInEth}(
                ""
            );
        }

        // Update spender's multiplier
        spenderStatus[sender] = SpenderStatus({
            multiplierTier: _multiplierTier,
            multiplier: selectedMultiplier.multiplier
        });

        // mint required amount of tokens for tier
        mintPointsETH(sender, amount);

        emit PurchaseMultiplier(
            sender,
            _multiplierTier,
            amountToUsd,
            selectedMultiplier.multiplier
        );
    }

    function updateMultiplierPrice(
        MultiplierTier _multiplierTier,
        uint256 _priceInUSD
    ) external onlyOwner {
        multiplierTierInfo[_multiplierTier].multiplierPrice = _priceInUSD;
        emit MultiplierPriceUpdated(_multiplierTier, _priceInUSD);
    }

    function updateMultiplier(
        MultiplierTier _multiplierTier,
        uint32 _multiplier
    ) external onlyOwner {
        multiplierTierInfo[_multiplierTier].multiplier = _multiplier;
        emit MultiplierUpdated(_multiplierTier, _multiplier);
    }

    function updateFundingFactoryAddress(
        address _newFactoryAddress
    ) external onlyOwner {
        fundingFactoryAddress = _newFactoryAddress;
        emit NewFundingFactoryAddress(_newFactoryAddress);
    }

    function pause(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    function mintPoints(
        address _spender,
        uint256 amount
    ) external whenNotPaused onlyFactory {
        uint256 multiplier = getSpenderMultiplier(_spender);
        spenderToPointsEarned[_spender] += amount * multiplier;
        emit PointsMinted(_spender, amount);
    }

    /*//////////////////////////////////////////////////////////////
                            PUBLIC FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function mintPointsETH(
        address _spender,
        uint256 amountSpent
    ) public whenNotPaused onlyFactory {
        uint256 amountSpendInUsd = amountSpent.ethToUsd(priceFeedAddress);
        uint256 pointsReceived = calAmountPoints(amountSpendInUsd);
        uint256 multiplier = getSpenderMultiplier(_spender);
        spenderToPointsEarned[_spender] += pointsReceived * multiplier;

        emit PointsMinted(_spender, pointsReceived);
    }

    function mintPointsUSD(
        address _spender,
        uint256 amountSpent
    ) external whenNotPaused onlyFactory {
        uint256 pointsReceived = calAmountPoints(amountSpent);
        uint256 multiplier = getSpenderMultiplier(_spender);
        spenderToPointsEarned[_spender] += pointsReceived * multiplier;

        emit PointsMinted(_spender, pointsReceived);
    }

    function updateMultiplierTierInfo(
        MultiplierTier _multiplierTier,
        uint256 _priceInUSD,
        uint32 _multiplier
    ) public onlyOwner {
        multiplierTierInfo[_multiplierTier] = MultiplierInfo({
            multiplier: _multiplier,
            multiplierPrice: _priceInUSD
        });

        emit MultiplierInfoUpdated(_multiplierTier, _multiplier, _priceInUSD);
    }

    function calAmountPoints(
        uint256 _amountSpentInUSD
    ) public pure returns (uint256) {
        return (_amountSpentInUSD * BASE_POINTS) / 1e18;
    }

    /*//////////////////////////////////////////////////////////////
                            GETTER FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function getMultiplierInfo(
        MultiplierTier _tier
    ) external view returns (MultiplierInfo memory) {
        return multiplierTierInfo[_tier];
    }

    function getMultiplierTierPrice(
        MultiplierTier _tier
    ) external view returns (uint256) {
        return multiplierTierInfo[_tier].multiplierPrice;
    }

    function getMultiplierTierMultiplier(
        MultiplierTier _tier
    ) external view returns (uint32) {
        return multiplierTierInfo[_tier].multiplier;
    }

    function getSpenderPoints(
        address _spender
    ) external view returns (uint256) {
        return spenderToPointsEarned[_spender];
    }

    function getSpenderStatus(
        address _spender
    ) external view returns (SpenderStatus memory) {
        return spenderStatus[_spender];
    }

    function getSpenderMultiplier(
        address _spender
    ) public view returns (uint32) {
        if (spenderStatus[_spender].multiplier == 0) {
            return BASE_TIER_MULTIPLIER;
        } else {
            return spenderStatus[_spender].multiplier;
        }
    }
}

contracts/ChainFundMe.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {ICapitaFundingFactory} from "./interfaces/ICapitaFundingFactory.sol";
import {PriceFeed} from "./lib/PriceFeed.sol";
import {AggregatorV3Interface} from "@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol";

contract ChainFundMe is Initializable {
    using PriceFeed for uint256;

    /*//////////////////////////////////////////////////////////////
                                 ERRORS
    //////////////////////////////////////////////////////////////*/

    error ChainFundMe__NotFactory();
    error ChainFundMe__NotOwner();
    error ChainFundMe__FundingPeriodOver();
    error ChainFundMe__FundingPeriodNotStarted();
    error ChainFundMe__FundingStillActive();
    error ChainFundMe__AlreadyApproved();
    error ChainFundMe__NotApproved();
    error ChainFundMe__WithdrawFailed();
    error ChainFundMe__TokenNotAllowed();
    error ChainFundMe__TokenTransferFailed();
    error ChainFundMe__ValueSentNotEqualAmount();
    error ChainFundMe__FundingPaused();
    error ChainFundMe__FeeTransferFailed_Token();
    error ChainFundMe__FeeTransferFailed_ETH();
    error ChainFundMe__InvalidAmount();
    error ChainFundMe__FundingNotApproved();
    error ChainFundMe__FundingDisapproved();
    error ChainFundMe__FundingLimitExceeded();

    /*//////////////////////////////////////////////////////////////
                                STRUCTS
    //////////////////////////////////////////////////////////////*/

    struct Funder {
        address funderAddress;
        address tokenAddress;
        uint256 amount;
    }

    /*//////////////////////////////////////////////////////////////
                            STATE VARIABLES
    //////////////////////////////////////////////////////////////*/

    uint256 public startTime;
    uint256 public endTime;

    bool public isWithdrawApproved;
    bool public isWithdrawalPointsMinted;
    bool public withdrawalApprovalRevoked;
    bool public fundingApproved;
    bool public fundingDisapproved;
    bool public ended;

    string public campaignMetadataUri;

    address public owner;
    address public stableCoinAddress;
    address public capitaTokenAddress;
    address[] public otherAcceptableTokens;

    address public fundingFactoryAddress;

    bool public isPaused;
    uint256 public fundersCount;

    mapping(address => mapping(address => uint256))
        public otherTokenContribution; // funder -> token -> amount funded
    mapping(address => uint256) public ethContribution;
    mapping(uint256 => Funder) public allFunders; // index -> funder -> funded

    /*//////////////////////////////////////////////////////////////
                                 EVENTS
    //////////////////////////////////////////////////////////////*/

    event Deposited(
        address indexed funder,
        address indexed otherToken,
        uint256 amount
    );
    event WithdrawApproved();
    event WithdrawnETH(address indexed owner, uint256 amount);
    event WithdrawnToken(
        address indexed toAddress,
        uint256 amount,
        address tokenAddress
    );
    event Paused(bool paused);
    event FailedOtherTokensWithdrawal(address[] otherTokensAddresses);
    event ApprovalRevoked(bool indexed revoked);
    event FundingApproved(bool isApproved);
    event FundingDisapproved(bool isDisapproved);
    event EndedCampaign(bool isEnded);

    /*//////////////////////////////////////////////////////////////
                               MODIFIERS
    //////////////////////////////////////////////////////////////*/

    modifier onlyOwner() {
        if (msg.sender != owner) revert ChainFundMe__NotOwner();
        _;
    }

    modifier campaignStarted() {
        if (block.timestamp < startTime)
            revert ChainFundMe__FundingPeriodNotStarted();
        _;
    }

    modifier campaignNotOver() {
        if (block.timestamp > endTime || ended)
            revert ChainFundMe__FundingPeriodOver();
        _;
    }

    modifier campaignNotInProgress() {
        if (block.timestamp > startTime && block.timestamp < endTime)
            revert ChainFundMe__FundingStillActive();
        _;
    }

    modifier onlyFactory() {
        if (msg.sender != fundingFactoryAddress)
            revert ChainFundMe__NotFactory();
        _;
    }

    /*//////////////////////////////////////////////////////////////
                               FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _owner,
        uint256 _startTime,
        uint256 _endTime,
        string memory _campaignMetadataUri,
        address _stableCoinAddress,
        address _capitaTokenAddress,
        address[] memory _otherAcceptableTokens,
        address _fundingFactoryAddress
    ) external initializer {
        owner = _owner;
        startTime = _startTime;
        endTime = _endTime;
        campaignMetadataUri = _campaignMetadataUri;

        stableCoinAddress = _stableCoinAddress;
        capitaTokenAddress = _capitaTokenAddress;
        otherAcceptableTokens = _otherAcceptableTokens;

        fundingFactoryAddress = _fundingFactoryAddress;
    }

    /*//////////////////////////////////////////////////////////////
                           EXTERNAL FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function deposit(
        address _anotherToken,
        uint256 _amount,
        address _contributor
    ) external payable campaignStarted campaignNotOver onlyFactory {
        ICapitaFundingFactory capitaFundingFactory = ICapitaFundingFactory(
            fundingFactoryAddress
        );
        uint8 platformFee = capitaFundingFactory.platformFee();
        address feeWallet = capitaFundingFactory.feeWalletAddress();

        if (isPaused) revert ChainFundMe__FundingPaused();

        bool limitsEnabled = getLimitsEnabled();

        if (limitsEnabled) {
            if (!fundingApproved) revert ChainFundMe__FundingNotApproved();
            if (fundingDisapproved) revert ChainFundMe__FundingDisapproved();
        }

        address tokenUsedForFunding;

        if (_anotherToken != address(0)) {
            // deposit with the token
            if (_amount <= 0) revert ChainFundMe__InvalidAmount();
            if (
                _anotherToken != stableCoinAddress &&
                _anotherToken != capitaTokenAddress &&
                !checkTokenAddress(_anotherToken)
            ) revert ChainFundMe__TokenNotAllowed();

            IERC20 token = IERC20(_anotherToken);
            bool success = token.transferFrom(
                _contributor,
                address(this),
                _amount
            );

            if (!success) revert ChainFundMe__TokenTransferFailed();

            // withdraw fees
            uint256 feeInOtherTokens = (_amount * platformFee) / 100;
            if (feeInOtherTokens > 0) {
                token.transfer(feeWallet, feeInOtherTokens);
            }

            tokenUsedForFunding = _anotherToken;

            // update funded amount
            otherTokenContribution[_contributor][_anotherToken] += _amount;
        } else {
            // deposit eth
            uint256 fundAmount = msg.value;
            if (fundAmount <= 0) revert ChainFundMe__InvalidAmount();
            if (_amount != fundAmount)
                revert ChainFundMe__ValueSentNotEqualAmount();

            // withdraw fee
            uint256 feeInEth = (fundAmount * platformFee) / 100;
            (bool success, ) = payable(feeWallet).call{value: feeInEth}("");
            if (!success) revert ChainFundMe__FeeTransferFailed_ETH();

            tokenUsedForFunding = address(0);
            // update funded amount
            ethContribution[_contributor] += fundAmount;
        }

        allFunders[fundersCount] = Funder({
            funderAddress: _contributor,
            tokenAddress: tokenUsedForFunding,
            amount: _amount
        });
        fundersCount++;

        emit Deposited(_contributor, tokenUsedForFunding, _amount);
    }

    function approveWithdraw()
        external
        campaignStarted
        campaignNotInProgress
        onlyFactory
    {
        if (isWithdrawApproved) revert ChainFundMe__AlreadyApproved();

        isWithdrawApproved = true;
        ended = true;
        emit WithdrawApproved();
    }

    function revokeApproval(bool _approvalRevoked) external onlyFactory {
        withdrawalApprovalRevoked = _approvalRevoked;
        emit ApprovalRevoked(_approvalRevoked);
    }

    function withdrawETH() external onlyFactory {
        bool limitsEnabled = getLimitsEnabled();
        if (limitsEnabled) {
            if (!isWithdrawApproved || withdrawalApprovalRevoked)
                revert ChainFundMe__NotApproved();
        }
        uint256 balance = address(this).balance;

        (bool success, ) = payable(owner).call{value: balance}("");
        if (!success) revert ChainFundMe__WithdrawFailed();

        emit WithdrawnETH(owner, balance);
    }

    function withdrawOtherTokens() external onlyFactory {
        bool limitsEnabled = getLimitsEnabled();
        if (limitsEnabled) {
            if (!isWithdrawApproved || withdrawalApprovalRevoked)
                revert ChainFundMe__NotApproved();
        }

        address[] memory tempArray = new address[](
            otherAcceptableTokens.length
        );
        uint256 failureCount = 0;
        for (uint256 i = 0; i < otherAcceptableTokens.length; i++) {
            address otherTokenAddress = (otherAcceptableTokens[i]);
            (
                bool otherToken_success,
                uint256 otherToken_transferred_amount,
                address otherToken_sentTo
            ) = _tokenTransfer(otherTokenAddress);

            if (otherToken_transferred_amount > 0) {
                if (!otherToken_success) {
                    tempArray[failureCount] = otherTokenAddress;
                    failureCount++;
                } else {
                    emit WithdrawnToken(
                        otherToken_sentTo,
                        otherToken_transferred_amount,
                        otherTokenAddress
                    );
                }
            }
        }
        if (failureCount > 0) {
            address[] memory failedTokens = new address[](failureCount);
            for (uint256 j = 0; j < failureCount; j++) {
                failedTokens[j] = tempArray[j];
            }
            emit FailedOtherTokensWithdrawal(failedTokens);
        }

        if (stableCoinAddress != address(0)) {
            (
                bool stable_success,
                uint256 stable_transferred_amount,
                address stable_sentTo
            ) = _tokenTransfer(stableCoinAddress);
            if (stable_transferred_amount > 0) {
                if (!stable_success) revert ChainFundMe__WithdrawFailed();
                emit WithdrawnToken(
                    stable_sentTo,
                    stable_transferred_amount,
                    stableCoinAddress
                );
            }
        }
        if (capitaTokenAddress != address(0)) {
            (
                bool capita_success,
                uint256 capita_transferred_amount,
                address capita_sentTo
            ) = _tokenTransfer(capitaTokenAddress);
            if (capita_transferred_amount > 0) {
                if (!capita_success) revert ChainFundMe__WithdrawFailed();
                emit WithdrawnToken(
                    capita_sentTo,
                    capita_transferred_amount,
                    capitaTokenAddress
                );
            }
        }
    }

    function endCampaign() external campaignStarted campaignNotOver onlyOwner {
        ended = true;
        endTime = block.timestamp;
        emit EndedCampaign(ended);
    }

    function updateEndTime(
        uint256 _endTime
    ) external campaignNotOver onlyOwner {
        endTime = _endTime;
    }

    function updateStartTime(
        uint256 _startTime
    ) external campaignNotInProgress campaignNotOver onlyOwner {
        startTime = _startTime;
    }

    function updatePause(bool pause) external onlyFactory {
        isPaused = pause;
        emit Paused(pause);
    }

    function updateMetadataURI(
        string memory _uri
    ) external campaignNotOver onlyOwner {
        campaignMetadataUri = _uri;
    }

    function updateFundingApproval() external onlyFactory {
        fundingApproved = true;
        emit FundingApproved(true);
    }

    function updateFundingDisapproval(bool disapproved) external onlyFactory {
        fundingDisapproved = disapproved;
        emit FundingDisapproved(disapproved);
    }

    function updateIsWithdrawalPointsMinted() external onlyFactory {
        isWithdrawalPointsMinted = true;
    }

    /*//////////////////////////////////////////////////////////////
                           INTERNAL FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function _tokenTransfer(
        address tokenAddress
    ) internal returns (bool, uint256, address) {
        bool success;
        IERC20 token = IERC20(tokenAddress);
        uint256 tokenBalance = token.balanceOf(address(this));

        if (tokenBalance > 0) {
            success = token.transfer(owner, tokenBalance);
        }
        return (success, tokenBalance, owner);
    }

    /*//////////////////////////////////////////////////////////////
                            PUBLIC FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function checkTokenAddress(
        address _tokenAddress
    ) public view returns (bool) {
        for (uint256 i = 0; i < otherAcceptableTokens.length; i++) {
            if (otherAcceptableTokens[i] == _tokenAddress) {
                return true;
            }
        }
        return false;
    }

    /*//////////////////////////////////////////////////////////////
                            GETTER FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function getFundersDetails() external view returns (Funder[] memory) {
        Funder[] memory funders = new Funder[](fundersCount);
        for (uint256 i = 0; i < fundersCount; i++) {
            funders[i] = allFunders[i];
        }
        return funders;
    }

    function getFunderEthContribution(
        address _funderAddress
    ) external view returns (uint256) {
        return ethContribution[_funderAddress];
    }

    function getFunderOtherTokenContribution(
        address _funderAddress,
        address tokenAddress
    ) external view returns (uint256) {
        return otherTokenContribution[_funderAddress][tokenAddress];
    }

    function getLimitsEnabled() public view returns (bool) {
        return ICapitaFundingFactory(fundingFactoryAddress).limitsEnabled();
    }
}

contracts/interfaces/ICapitaFundingFacto.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface ICapitaFundingFactory {
    /*//////////////////////////////////////////////////////////////
                                 ERRORS
    //////////////////////////////////////////////////////////////*/
    error CapitaFundingFactory__NotModerator();
    error CapitaFundingFactory__InsufficientFee();
    error CapitaFundingFactory__WithdrawFailed();
    error CapitaFundingFactory__TokenNotAllowed(address _tokenAddress);
    error CapitaFundingFactory__InvalidAddress(address);
    error CapitaFundingFactory__FeeCannotBeLessThan_1();
    error CapitaFundingFactory__FeeCannotBeGreaterThan_20();
    error CapitaFundingFactory__ContractPaused();
    error CapitaFundingFactory__MaxOf5TokensExceeded();
    error CapitaFundingFactory__InvalidDatesSet();
    error CapitaFundingFactory__CapitaPointsAlreadySet();
    error CapitaFundingFactory__CampaignApproved(address);

    /*//////////////////////////////////////////////////////////////
                                 EVENTS
    //////////////////////////////////////////////////////////////*/
    event ChainFundMeCreated(
        address indexed creator,
        address indexed fundMeAddress
    );
    event ModeratorAdded(address indexed moderator);
    event ModeratorRemoved(address indexed moderator);
    event CapitaPointsAddressSet(address indexed capitaPointsAddress);
    event FeeWithdrawn(uint256 amount);
    event UpdatedFeeWalletAddress(address indexed _feeWalletAddress);
    event CapitaFactoryPaused(bool isPaused);
    event PlatformFeeUpdated(uint8 newFee);
    event AcceptableTokenSet(address indexed token, bool accepted);

    /*//////////////////////////////////////////////////////////////
                              VIEW FUNCTIONS
    //////////////////////////////////////////////////////////////*/
    function stableCoinAddress() external view returns (address);

    function capitaTokenAddress() external view returns (address);

    function feeWalletAddress() external view returns (address);

    function paused() external view returns (bool);

    function platformFee() external view returns (uint8);

    function limitsEnabled() external view returns (bool);

    function deployedCampaignsCount() external view returns (uint256);

    function checkAcceptableTokenAddress(
        address _tokenAddress
    ) external view returns (bool);

    function getUserCampaigns(
        address _user
    ) external view returns (address[] memory);

    function getDeployedCampaigns() external view returns (address[] memory);

    function verifiedCreators(address _creator) external view returns (bool);

    function priceFeedAddress() external view returns (address);

    function unverifiedFundLimit() external view returns (uint256);

    /*//////////////////////////////////////////////////////////////
                            MUTATIVE FUNCTIONS
    //////////////////////////////////////////////////////////////*/
    function createChainFundMe(
        uint256 startTime,
        uint256 endTime,
        string calldata _metadataUri,
        address[] calldata _otherTokenAddresses
    ) external;

    function removeModerator(address _moderator) external;

    function setCapitaPointsAddress(address _capitaPointsAddress) external;

    function setAcceptableToken(address _tokenAddress) external;

    function removeTokenAddress(address _tokenAddress) external;

    function updatePlatformFee(uint8 _platformFee) external;

    function updateFeeWalletAddress(address _feeWalletAddress) external;

    function updatePaused(bool _paused) external;

    function updateCapitaTokenAddress(address _capitaTokenAddress) external;

    function addModerator(address _moderator) external;

    function chainFundMe_fundChainFundMe(
        address _campaignAddress,
        address _otherToken,
        uint256 _amount
    ) external payable;

    function chainFundMe_approveWithdraw(address _campaignAddress) external;

    function chainFundMe_batchWithdrawApproval(
        address[] calldata _fundMeAddresses
    ) external;

    function chainFundMe_revokeApproval(
        address _campaignAddress,
        bool revoke
    ) external;

    function chainFundMe_pauseChainFundMeContract(
        address _campaignAddress,
        bool pause
    ) external;

    function chainFundMe_approveFunding(address _campaignAddress) external;

    function chainFundMe_batchApproveFunding(
        address[] calldata _fundMeAddresses
    ) external;

    function chainFundMe_disapproveFunding(
        address _campaignAddress,
        bool _disapproved
    ) external;

    function chainFundMe_batchDisapproveFunding(
        address[] calldata _fundMeAddresses,
        bool _disapproved
    ) external;

    function chainFundMe_withdrawETH(
        address _campaignAddress,
        address _toAddress
    ) external;

    function chainFundMe__withdrawTokens(
        address _campaignAddress,
        address _toAddress
    ) external;
}

contracts/lib/PriceFeed.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {AggregatorV3Interface} from "@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol";
import "hardhat/console.sol";

library PriceFeed {
    error Stale_Price();
    error Invalid_Price();

    function ethToUsd(
        uint256 ethAmount,
        AggregatorV3Interface dataFeed
    ) internal view returns (uint256) {
        uint256 ethPriceInUsd = getChainlinkDataFeedLatestAnswer(dataFeed);
        uint256 ethAmountInUsd = ((ethPriceInUsd) * ethAmount) / 10 ** 18;

        return ethAmountInUsd;
    }

    function usdToEth(
        uint256 usdAmount,
        AggregatorV3Interface dataFeed
    ) internal view returns (uint256) {
        uint256 ethPriceInUsd = getChainlinkDataFeedLatestAnswer(dataFeed);

        uint256 usdAmountInEth = (usdAmount / (ethPriceInUsd)) * 10 ** 18;

        return usdAmountInEth;
    }

    /**
     * Returns the latest answer.
     */
    function getChainlinkDataFeedLatestAnswer(
        AggregatorV3Interface dataFeed
    ) internal view returns (uint256) {
        // prettier-ignore
        (
            /* uint80 roundID */,
            int answer,
            /*uint startedAt*/,
            uint timeStamp,
            /*uint80 answeredInRound*/
        ) = dataFeed.latestRoundData();

        if (timeStamp < (block.timestamp - 2 hours)) revert Stale_Price();
        if (answer <= 0) revert Invalid_Price();
        return (uint256(answer) * 10 ** 10);
    }
}

